const item = $input.first().json;

const headers = item.headers || {};
const body = item.body || {};

const email = body.email || "";

// Extract domain
let domain = null;
if (email.includes("@")) {
  domain = email.split("@")[1].toLowerCase();
}

// List of public email providers to ignore
const publicDomains = [
  "gmail.com",
  "yahoo.com",
  "hotmail.com",
  "outlook.com",
  "live.com",
  "msn.com",
  "rediffmail.com",
  "icloud.com",
  "aol.com",
  "protonmail.com",
  "yandex.com"
];

// Determine if business email
const isBusinessEmail = domain && !publicDomains.includes(domain);

return [
  {
    json: {
      name: body.name || null,
      email: email,
      email_domain: domain,
      is_business_email: isBusinessEmail,

      linkedin: body.linkedin || null,
      message: body.message || null,
      source: body.source || null,
      referred_by: body.referred_by || null,

      ip_address: headers["x-forwarded-for"] || headers["x-real-ip"] || null,
      user_agent: headers["user-agent"] || null,

      received_at: new Date().toISOString()
    }
  }
];

