// Sequencer - Decide & Template (improved)
const lead = $input.first().json || {};
const id = lead.id;
const email = (lead.email || '').toString().trim().toLowerCase();
const name = (lead.name || '').toString().trim();
const segmentRaw = (lead.segment || '').toString().trim();
const segment = segmentRaw || 'SMB';
const lastStage = Number(lead.email_sequence_stage || 0);
const emailOpened = !!lead.email_opened;
const linkClicked = !!lead.link_clicked;
const sequenceActive = (lead.sequence_active === undefined) ? true : !!lead.sequence_active;

// engagement = opened or clicked or demo requested (if available)
const engaged = emailOpened || linkClicked || (lead.demo_requested === true);

// if no email or sequence inactive or already finished
if (!email || !sequenceActive || lastStage >= 4) {
  return [{ json: { id, email, sendEmail: null, reason: 'no_send_conditions' } }];
}

// choose next stage
let nextStage = lastStage + 1;
if (!engaged && lastStage === 3) {
  nextStage = 4; // send break-up
}
if (nextStage > 4) nextStage = 4;

// templates (short) — fallback to SMB
const templates = {
  "Enterprise": {
    1: { subject: `Welcome — quick question about ${lead.company || '[Company]'}`, html: `<p>Hi ${name || ''},</p><p>Quick question about ${lead.company || ''} — how do you currently handle lead follow-up?</p><p>Best,<br/>[Your name]</p>` },
    2: { subject: `How ${lead.company || '[Company]'} automated lead qualification`, html: `<p>Hi ${name || ''},</p><p>Case study: automated segmentation & alerts. See: https://example.com/case-study?cid=${id}</p>` },
    3: { subject: `15 mins to show you the system?`, html: `<p>Hi ${name || ''},</p><p>Quick demo: https://example.com/demo?cid=${id}</p>` },
    4: { subject: `Should I close your file?`, html: `<p>Hi ${name || ''},</p><p>Before I close your file — interested or not?</p>` }
  },
  "Mid-Market": {
    1: { subject: `Quick start for ${lead.company || '[Company]'}`, html: `<p>Hi ${name || ''},</p><p>Guide: https://example.com/guide?cid=${id}</p>` },
    2: { subject: `How mid-market teams saved 10 hrs/week`, html: `<p>Hi ${name || ''},</p><p>Case study: https://example.com/case-study?cid=${id}</p>` },
    3: { subject: `Demo this week?`, html: `<p>Hi ${name || ''},</p><p>Book: https://example.com/demo?cid=${id}</p>` },
    4: { subject: `Last email (promise)`, html: `<p>Hi ${name || ''},</p><p>Closing your file unless you want follow-up.</p>` }
  },
  "SMB": {
    1: { subject: `Free template: Lead nurture automation`, html: `<p>Hi ${name || ''},</p><p>Free template: https://example.com/template?cid=${id}</p>` },
    2: { subject: `3 automation wins for small teams`, html: `<p>Hi ${name || ''},</p><p>How small teams automate: https://example.com/case-study?cid=${id}</p>` },
    3: { subject: `Quick demo?`, html: `<p>Hi ${name || ''},</p><p>Book: https://example.com/demo?cid=${id}</p>` },
    4: { subject: `Closing your file`, html: `<p>Hi ${name || ''},</p><p>Should I close your file or check back in 3 months?</p>` }
  }
};

const segKey = templates[segment] ? segment : 'SMB';
const tpl = templates[segKey][nextStage] || templates['SMB'][nextStage];

if (!tpl || !tpl.subject || !tpl.html) {
  return [{ json: { id, email, sendEmail: null, reason: 'missing_template' } }];
}

// compute next schedule (ISO) for DB
let nextEmailISO = null;
let keepSequence = true;
if (nextStage === 1) {
  // initial send -> schedule email 2 in 3 days
  nextEmailISO = new Date(Date.now() + 3 * 24 * 3600 * 1000).toISOString();
} else if (nextStage === 2) {
  nextEmailISO = new Date(Date.now() + 3 * 24 * 3600 * 1000).toISOString();
} else if (nextStage === 3) {
  nextEmailISO = new Date(Date.now() + 2 * 24 * 3600 * 1000).toISOString();
} else if (nextStage === 4) {
  nextEmailISO = null;
  keepSequence = false;
}

// final skip if lead marked Hot or lead_score >= 50
if ((lead.status || '').toString().toLowerCase() === 'hot' || (Number(lead.lead_score || 0) >= 50)) {
  return [{ json: { id, email, sendEmail: null, reason: 'hot_lead_skip' } }];
}

return [{
  json: {
    id,
    email,
    segment: segKey,
    previous_stage: lastStage,
    sendEmail: nextStage,
    subject: tpl.subject,
    html: tpl.html,
    next_email_scheduled: nextEmailISO,
    sequence_active: keepSequence
  }
}];
